class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int total = 0;
        for (int x : nums) total += x;
        if ((total + target) < 0 || (total + target) % 2 != 0) return 0;
        int s = (total + target) / 2;
        vector<int> dp(s + 1, 0);
        dp[0] = 1;
        for (int x : nums) {
            for (int j = s; j >= x; --j) {
                dp[j] += dp[j - x];
            }
        }
        return dp[s];
    }
};

class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int total = 0;
        for (int x : nums) total += x;
        if ((total + target) < 0 || (total + target) % 2 != 0) return 0;
        int s = (total + target) / 2;
        int[] dp = new int[s + 1];
        dp[0] = 1;
        for (int x : nums) {
            for (int j = s; j >= x; j--) {
                dp[j] += dp[j - x];
            }
        }
        return dp[s];
    }
}

var findTargetSumWays = function(nums, target) {
    const total = nums.reduce((a, b) => a + b, 0);
    if ((total + target) < 0 || (total + target) % 2 !== 0) return 0;
    const s = Math.floor((total + target) / 2);
    const dp = new Array(s + 1).fill(0);
    dp[0] = 1;
    for (const x of nums) {
        for (let j = s; j >= x; j--) {
            dp[j] += dp[j - x];
        }
    }
    return dp[s];
};
